"""Literal, slow reference implementation used only for cross-checking."""
import struct, zlib, hashlib, sys
sys.path.insert(0, '/workspace/project')
from wire import packet as wpkt, payload as wpayload

MASK24 = 0xFFFFFF
FNV_OFFSET = 14695981039346656037
FNV_PRIME = 1099511628211
MASK64 = (1 << 64) - 1
NAMES = ('allreduce', 'reduce', 'broadcast', 'barrier', 'allgather', 'reducescatter')


def ord_of(d, s):
    n = 0
    for r in range(4):
        if r == d:
            continue
        if r == s:
            return n
        n += 1
    raise AssertionError


def rank_of(d, o):
    n = 0
    for r in range(4):
        if r == d:
            continue
        if n == o:
            return r
        n += 1
    raise AssertionError


class Ref(object):
    def __init__(self, prim, mode, root, K, D, N, start, tlimit):
        self.prim = prim
        self.mode = mode
        self.root = root
        self.K = K
        self.D = D
        self.N = N
        self.start = start
        self.tlimit = tlimit
        self.contrib = {}          # (p, r) -> payload bytes
        self.S = [0, 0, 0, 0]
        self.A = [0, 0, 0, 0]
        self.U = [0, 0, 0, 0]
        self.repeat = [False] * 4
        self.b = 0
        self.budget = -1
        self.tape = hashlib.sha256()
        self.packets = 0
        self.ebytes = 0
        self.trace = []
        self.snaps = []
        self.c = dict(data=0, ack=0, txdata=0, txack=0, new=0, dup=0, blk=0,
                      stale=0, winv=0, einv=0, ign=0, fail=0)

    # ---------------- derived state ----------------
    def sources(self):
        return [self.root] if self.prim == 'broadcast' else [0, 1, 2, 3]

    def R(self, r):
        n = 0
        while (n, r) in self.contrib:
            n += 1
        return n

    def complete(self, p):
        return all((p, r) in self.contrib for r in self.sources())

    def occupied(self):
        b = self.retire_prefix()
        return sorted(p for (p, r) in self.contrib if p >= b)

    def mask_of(self, p):
        m = 0
        for r in range(4):
            if (p, r) in self.contrib:
                m |= 1 << r
        return m

    def aggregate(self, p):
        words = [0] * self.D
        for r in self.sources():
            if (p, r) in self.contrib:
                add = struct.unpack('!%dI' % self.D, self.contrib[(p, r)])
                words = [(a + x) & 0xFFFFFFFF for a, x in zip(words, add)]
        return words

    def result_payload(self, d, q):
        """Payload of destination d's output record q, or None if not ready."""
        prim = self.prim
        if prim == 'allreduce':
            p = q
            if q >= self.K:
                return None
            dests = [0, 1, 2, 3]
        elif prim == 'reduce':
            if d != self.root or q >= self.K:
                return None
            p = q
            dests = [self.root]
        elif prim == 'broadcast':
            if d == self.root or q >= self.K:
                return None
            p = q
            dests = [r for r in range(4) if r != self.root]
        elif prim == 'barrier':
            if q >= 1:
                return None
            p = 0
            dests = [0, 1, 2, 3]
        elif prim == 'allgather':
            if q >= 3 * self.K:
                return None
            p = q // 3
            dests = [0, 1, 2, 3]
        else:
            block = self.K // 4
            if q >= block:
                return None
            p = d * block + q
            dests = [0, 1, 2, 3]
        if d not in dests:
            return None
        if not self.complete(p):
            return None
        if p < self.retire_prefix():
            return None
        if prim == 'allgather':
            return self.contrib[(p, rank_of(d, q % 3))]
        if prim == 'broadcast':
            return self.contrib[(p, self.root)]
        if prim == 'barrier':
            return b''
        return struct.pack('!%dI' % self.D, *self.aggregate(p))

    def outputs_acked(self, p):
        A = self.A
        prim = self.prim
        if prim in ('allreduce', 'barrier'):
            return all(A[d] > (p if prim == 'allreduce' else 0) for d in range(4))
        if prim == 'reduce':
            return A[self.root] > p
        if prim == 'broadcast':
            return all(A[d] > p for d in range(4) if d != self.root)
        if prim == 'allgather':
            return all(A[d] > 3 * p + 2 for d in range(4))
        block = self.K // 4
        return A[p // block] > p % block

    def retire_prefix(self):
        b = 0
        while b < self.K:
            if not self.complete(b):
                break
            if not self.outputs_acked(b):
                break
            if not all(self.U[r] > b for r in self.sources()):
                break
            b += 1
        return b

    def safe(self, p, r):
        if self.mode == 3:
            return True
        prim = self.prim
        A = self.A
        if prim in ('allreduce', 'barrier'):
            return A[r] > p
        if prim == 'reduce':
            return A[self.root] > p
        if prim == 'broadcast':
            return all(A[d] > p for d in range(4) if d != self.root)
        if prim == 'reducescatter':
            block = self.K // 4
            return A[p // block] > p % block
        return all(A[d] > 3 * p + ord_of(d, r) for d in range(4) if d != r)

    def E(self, r):
        e = 0
        while e < self.R(r) and self.safe(e, r):
            e += 1
        return e

    # ---------------- wire ----------------
    def emit(self, rank, frame):
        if self.budget == 0:
            self.c['fail'] += 1
            return False
        if self.budget > 0:
            self.budget -= 1
        self.tape.update(bytes((rank,)) + struct.pack('<I', len(frame)))
        self.tape.update(bytes(frame))
        self.packets += 1
        self.ebytes += len(frame)
        if len(self.trace) < self.tlimit:
            self.trace.append({'rank': rank, 'hex': bytes(frame).hex()})
        return True

    def send_ack(self, r, prefix):
        psn = (self.start + prefix - 1) & MASK24
        return self.emit(r, wpkt(r, psn, ack=True, outgoing=True))

    def send_result(self, d, q, body):
        psn = (self.start + q) & MASK24
        return self.emit(d, wpkt(d, psn, body, outgoing=True))

    def service(self, retry=-1):
        for r in range(4):
            e = self.E(r)
            if e > 0 and (e > self.U[r] or self.repeat[r]):
                if not self.send_ack(r, e):
                    self.finish()
                    return
                self.U[r] = e
                self.repeat[r] = False
        if retry >= 0:
            d = retry
            q = self.A[d]
            while q < self.S[d]:
                body = self.result_payload(d, q)
                if body is None:
                    break
                if not self.send_result(d, q, body):
                    self.finish()
                    return
                self.c['txdata'] += 1
                q += 1
        for d in range(4):
            q = self.S[d]
            while True:
                body = self.result_payload(d, q)
                if body is None:
                    break
                if not self.send_result(d, q, body):
                    self.finish()
                    return
                self.c['txdata'] += 1
                q += 1
                self.S[d] = q
        self.finish()

    def finish(self):
        self.b = self.retire_prefix()

    # ---------------- ingress ----------------
    def ingress(self, rank, frame):
        info = validate(frame, self.D)
        if info is None:
            self.c['winv'] += 1
            return
        op, psn, payload = info
        host_mac = bytes((2, 0, 0, 0, 0, rank + 1))
        sw_mac = bytes((2, 1, 0, 0, 0, rank + 1))
        host_ip = bytes((10, 0, 0, rank + 1))
        sw_ip = bytes((10, 0, 0, 101 + rank))
        if (frame[0:6] != sw_mac or frame[6:12] != host_mac
                or frame[26:30] != host_ip or frame[30:34] != sw_ip
                or frame[46:50] != bytes((0, 0, 2, rank))):
            self.c['einv'] += 1
            return
        if op == 4:
            p = (psn - self.start) & MASK24
            if p >= self.K or (self.prim == 'broadcast' and rank != self.root):
                self.c['einv'] += 1
                return
            self.c['data'] += 1
            b = self.b
            if p < b:
                self.c['stale'] += 1
                self.repeat[rank] = True
                self.service()
                return
            if p >= b + self.N:
                self.c['blk'] += 1
                self.service()
                return
            if (p, rank) in self.contrib:
                self.c['dup'] += 1
                self.repeat[rank] = True
                self.service()
                return
            self.contrib[(p, rank)] = payload
            self.c['new'] += 1
            self.service()
            return
        self.c['ack'] += 1
        length = (psn - self.start + 1) & MASK24
        if self.A[rank] < length <= self.S[rank]:
            self.A[rank] = length
        else:
            self.c['ign'] += 1
        self.service()

    # ---------------- replay ----------------
    def replay(self, events):
        for op in events:
            name = op['op']
            if name == 'data':
                r = op['rank']
                for i in range(op.get('count', 1)):
                    p = op['p'] + i * op.get('step', 1)
                    if 'values' in op:
                        body = struct.pack('!%dI' % len(op['values']), *op['values'])
                    else:
                        body = wpayload(op.get('seed', 0), p, r, self.D)
                    f = bytearray(wpkt(r, (self.start + p) & MASK24, body))
                    for off, val in op.get('xor', []):
                        f[off] ^= val
                    self.ingress(r, f)
            elif name == 'ack':
                self.ingress(op['rank'], wpkt(op['rank'],
                                              (self.start + op['upto'] - 1) & MASK24,
                                              ack=True))
            elif name == 'wire':
                self.ingress(op['rank'], bytes.fromhex(op['hex']))
            elif name == 'train':
                end = op['p'] + op['count']
                K = self.K
                root = self.root
                for lo in range(op['p'], end, op['width']):
                    hi = min(end, lo + op['width'])
                    for r in op['ranks']:
                        if self.prim == 'broadcast' and r != root:
                            continue
                        seq = range(hi - 1, lo - 1, -1) if op.get('reverse', False) else range(lo, hi)
                        for p in seq:
                            self.ingress(r, wpkt(r, (self.start + p) & MASK24,
                                                 wpayload(op.get('seed', 0), p, r, self.D)))
                    for r in range(4):
                        if self.prim == 'allgather':
                            n = 3 * hi
                        elif self.prim == 'reducescatter':
                            n = max(0, min(K // 4, hi - r * (K // 4)))
                        elif self.prim == 'reduce':
                            n = hi if r == root else 0
                        elif self.prim == 'broadcast':
                            n = hi if r != root else 0
                        else:
                            n = hi
                        self.ingress(r, wpkt(r, (self.start + n - 1) & MASK24, ack=True))
            elif name == 'flush':
                self.service()
            elif name == 'retry':
                self.repeat[op['rank']] = True
                self.service(op['rank'])
            elif name == 'budget':
                self.budget = op['n']
            elif name == 'snap':
                self.snaps.append({'tag': op['tag'], 'state': self.state_list(),
                                   'buffer': self.digest_hex(),
                                   'wire_sha256': self.tape.hexdigest(),
                                   'packets': self.packets, 'bytes': self.ebytes})
            else:
                raise ValueError(name)

    # ---------------- certificates ----------------
    def state_list(self):
        occ = self.occupied()
        c = self.c
        return [self.retire_prefix(), len(occ),
                self.R(0), self.R(1), self.R(2), self.R(3),
                self.S[0], self.S[1], self.S[2], self.S[3],
                self.A[0], self.A[1], self.A[2], self.A[3],
                self.U[0], self.U[1], self.U[2], self.U[3],
                c['data'], c['ack'], c['txdata'], c['txack'],
                c['new'], c['dup'], c['blk'], c['stale'],
                c['winv'], c['einv'], c['ign'], c['fail'], 0, 0]

    def digest(self):
        h = FNV_OFFSET
        for p in self.occupied():
            for i in range(8):
                h = ((h ^ ((p >> (8 * i)) & 0xFF)) * FNV_PRIME) & MASK64
            h = ((h ^ self.mask_of(p)) * FNV_PRIME) & MASK64
            h = ((h ^ (1 if self.complete(p) else 0)) * FNV_PRIME) & MASK64
            if self.prim == 'allgather':
                for r in range(4):
                    if (p, r) in self.contrib:
                        h = ((h ^ 1) * FNV_PRIME) & MASK64
                        for x in self.contrib[(p, r)]:
                            h = ((h ^ x) * FNV_PRIME) & MASK64
                    else:
                        h = (h * FNV_PRIME) & MASK64
            elif self.prim == 'broadcast':
                for x in self.contrib[(p, self.root)]:
                    h = ((h ^ x) * FNV_PRIME) & MASK64
            elif self.prim == 'barrier':
                pass
            else:
                for w in self.aggregate(p):
                    for i in range(4):
                        h = ((h ^ ((w >> (8 * i)) & 0xFF)) * FNV_PRIME) & MASK64
        return h

    def digest_hex(self):
        return '%016x' % self.digest()

    def certificate(self):
        return {'state': self.state_list(), 'buffer': self.digest_hex(),
                'wire_sha256': self.tape.hexdigest(), 'packets': self.packets,
                'bytes': self.ebytes, 'snapshots': self.snaps,
                'trace': self.trace}


def validate(frame, D):
    """Return (opcode, psn, payload) for a wire-valid frame else None."""
    frame = bytes(frame)
    n = len(frame)
    if n < 58:
        return None
    if frame[12:14] != b'\x08\x00' or frame[14] != 0x45:
        return None
    ip_total = int.from_bytes(frame[16:18], 'big')
    if n != 14 + ip_total:
        return None
    if frame[23] != 17:
        return None
    if frame[20:22] not in (b'\x00\x00', b'\x40\x00'):
        return None
    hdr = bytearray(frame[14:34])
    hdr[10:12] = b'\x00\x00'
    s = sum(struct.unpack('!10H', bytes(hdr)))
    while s >> 16:
        s = (s & 0xFFFF) + (s >> 16)
    if ((~s) & 0xFFFF) != int.from_bytes(frame[24:26], 'big'):
        return None
    if frame[34:36] != b'\x12\xb7' or frame[36:38] != b'\x12\xb7':
        return None
    udp_len = int.from_bytes(frame[38:40], 'big')
    if udp_len != ip_total - 20:
        return None
    if frame[40:42] != b'\x00\x00':
        return None
    op = frame[42]
    if frame[43] != 0 or frame[44:46] != b'\xff\xff':
        return None
    if frame[46] != 0:
        return None
    psn = int.from_bytes(frame[50:54], 'big') & MASK24
    if op == 4:
        if frame[50] != 0x80:
            return None
        if udp_len - 24 != 4 * D:
            return None
        payload = frame[54:54 + 4 * D]
    elif op == 0x11:
        if frame[50] != 0:
            return None
        if udp_len != 28:
            return None
        if frame[54:58] != struct.pack('!I', 0x1F000000 | ((psn + 1) & MASK24)):
            return None
        payload = frame[54:58]
    else:
        return None
    crc = bytearray(b'\xff' * 8 + frame[14:n - 4])
    crc[9] = 0xFF
    crc[16] = 0xFF
    crc[18:20] = b'\xff\xff'
    crc[34:36] = b'\xff\xff'
    crc[40] = 0xFF
    if zlib.crc32(bytes(crc)) != int.from_bytes(frame[n - 4:n], 'little'):
        return None
    return op, psn, payload
